import {
  Group,
  IcosahedronGeometry,
  InstancedMesh,
  MeshBasicNodeMaterial,
  Color,
  Matrix4,
  AdditiveBlending,
  BufferAttribute,
  InstancedBufferAttribute,
  MathUtils,
  Object3D,
} from 'three/webgpu';
import {
  tslFn,
  uniform,
  time,
  instanceIndex,
  instancedBufferAttribute,
  sin,
  cos,
  vec3,
  float,
  positionLocal,
  instanceMatrix,
  modelWorldMatrix,
  cameraPosition,
  F,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // --- Parse config ---
  const colors = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // --- Root group ---
  const group = new Group();
  group.name = 'particle-constellation';

  // --- Constants ---
  const FIELD_COUNT = 1110; // 1200 - 90 core
  const CORE_COUNT = 90;
  const TOTAL = FIELD_COUNT + CORE_COUNT;

  const ELLIPSOID_RADIUS = new THREE.Vector3(3, 2, 2.5); // half extents
  const ELLIPSOID_CENTER = new THREE.Vector3(0, 0, -1.5);
  const CORE_RADIUS = 0.5;

  // --- Generate positions ---
  const fieldPositions = [];
  const corePositions = [];

  // Field positions on ellipsoid shell
  for (let i = 0; i < FIELD_COUNT; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const r = 1; // surface
    const x = r * Math.sin(phi) * Math.cos(theta) * ELLIPSOID_RADIUS.x;
    const y = r * Math.sin(phi) * Math.sin(theta) * ELLIPSOID_RADIUS.y;
    const z = r * Math.cos(phi) * ELLIPSOID_RADIUS.z;
    fieldPositions.push(new THREE.Vector3(x, y, z).add(ELLIPSOID_CENTER));
  }

  // Core positions inside sphere at origin
  for (let i = 0; i < CORE_COUNT; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const r = Math.cbrt(Math.random()) * CORE_RADIUS; // uniform volume
    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);
    corePositions.push(new THREE.Vector3(x, y, z));
  }

  // --- Create geometries and materials ---
  const icoGeo = new IcosahedronGeometry(0.012, 1);

  // Field mesh
  const fieldMat = new MeshBasicNodeMaterial({
    color: colors.paper,
    emissive: colors.paper,
    emissiveIntensity: 0.9,
    transparent: true,
    depthWrite: false,
  });

  // Override opacity using per-instance attribute
  const opacityFn = tslFn(([attrOpacity]) => {
    return attrOpacity;
  });
  fieldMat.opacityNode = opacityFn(instancedBufferAttribute('aOpacity', 'float'));

  const fieldMesh = new InstancedMesh(icoGeo, fieldMat, FIELD_COUNT);
  fieldMesh.name = 'field-particles';

  // Set instance matrices and opacity attribute
  const dummy = new Object3D();
  const opacityArray = new Float32Array(FIELD_COUNT);
  fieldMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage); // for drift

  fieldPositions.forEach((pos, i) => {
    dummy.position.copy(pos);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);

    // Depth falloff opacity
    const z = pos.z + 1.5; // relative to ellipsoid center? Actually we need z relative to world z = 0? The falloff is based on world z? Spec says "depth falloff: per-instance opacity 0.9 at z=0 falling linearly to 0.15 at z=-5". So we use the node's local z. Since group is at (0,0,0), local z is the same.
    const localZ = pos.z;
    const opacity = MathUtils.clamp(0.9 + (localZ / 5) * 0.75, 0.15, 0.9);
    opacityArray[i] = opacity;
  });
  fieldMesh.instanceMatrix.needsUpdate = true;

  fieldMesh.geometry.setAttribute(
    'aOpacity',
    new InstancedBufferAttribute(opacityArray, 1)
  );
  group.add(fieldMesh);

  // Core mesh
  const coreMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  });

  // Core pulse: modulate emissiveIntensity with sine
  const pulseTime = uniform(0);
  const corePulseFn = tslFn(() => {
    return float(1.5 + 0.3 * sin(pulseTime.mul(2 * Math.PI * 0.1)));
  });
  coreMat.emissiveIntensityNode = corePulseFn();

  const coreMesh = new InstancedMesh(icoGeo, coreMat, CORE_COUNT);
  coreMesh.name = 'core-particles';

  corePositions.forEach((pos, i) => {
    dummy.position.copy(pos);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  });
  coreMesh.instanceMatrix.needsUpdate = true;

  group.add(coreMesh);

  // --- Ambient Drift (update matrices on tick) ---
  const fieldOriginalPositions = fieldPositions.map(p => p.clone());
  const coreOriginalPositions = corePositions.map(p => p.clone());
  const phases = new Float32Array(TOTAL);
  for (let i = 0; i < TOTAL; i++) {
    phases[i] = Math.random() * Math.PI * 2;
  }

  const driftTicker = () => {
    const t = performance.now() / 1000;
    const freq = 0.05;
    const amp = 0.04;

    // Update field
    for (let i = 0; i < FIELD_COUNT; i++) {
      const orig = fieldOriginalPositions[i];
      const offsetX = amp * Math.sin(2 * Math.PI * freq * t + phases[i]);
      const offsetY = amp * Math.sin(2 * Math.PI * freq * t * 0.7 + phases[i] + 1.2);
      const offsetZ = amp * Math.sin(2 * Math.PI * freq * t * 1.3 + phases[i] + 2.5);
      dummy.position.set(
        orig.x + offsetX,
        orig.y + offsetY,
        orig.z + offsetZ
      );
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    // Update core (optional drift, smaller)
    for (let i = 0; i < CORE_COUNT; i++) {
      const orig = coreOriginalPositions[i];
      const offsetX = (amp * 0.5) * Math.sin(2 * Math.PI * freq * t * 1.1 + phases[FIELD_COUNT + i]);
      const offsetY = (amp * 0.5) * Math.sin(2 * Math.PI * freq * t * 0.9 + phases[FIELD_COUNT + i] + 1.5);
      const offsetZ = (amp * 0.5) * Math.sin(2 * Math.PI * freq * t * 1.2 + phases[FIELD_COUNT + i] + 0.8);
      dummy.position.set(
        orig.x + offsetX,
        orig.y + offsetY,
        orig.z + offsetZ
      );
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  };

  // Add ticker
  gsap.ticker.add(driftTicker);

  // --- Core pulse GSAP ---
  const pulseTimeline = gsap.to(coreMat, {
    emissiveIntensity: 1.5,
    duration: 5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut',
  });

  // --- Text elements ---
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: -0.01,
  });
  heroText.position.set(0, 0.5, 0.5);
  heroText.scale.setScalar(1); // adjust if needed
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.02,
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.08,
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // --- Apply particle-emerge primitive ---
  const primitiveResult = ctx.primitives['particle-emerge'](group, {
    count: TOTAL,
    durationMs: 1400,
  });

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Remove ticker
    gsap.ticker.remove(driftTicker);
    // Kill pulse
    pulseTimeline.kill();
    // Kill primitive timeline
    if (primitiveResult && primitiveResult.cleanup) {
      primitiveResult.cleanup();
    }
    // Dispose geometries and materials
    icoGeo.dispose();
    fieldMat.dispose();
    coreMat.dispose();
    fieldMesh.geometry.dispose();
    coreMesh.geometry.dispose();
    // Text disposal (handle via font atlas cleanup? We assume font atlas manages)
  };

  return group;
}
